script:
frappe.ui.form.on('Player', {
    validate: function(frm) {

        if (frm.doc.jersey_number < 1 || frm.doc.jersey_number > 99) {
            frappe.throw("Jersey Number must be between 1 and 99");
        }

        if (frm.doc.rating < 0 || frm.doc.rating > 10) {
            frappe.throw("Rating must be between 0 and 10");
        }

        if (frm.doc.contract_start && frm.doc.contract_end) {
            if (frm.doc.contract_end < frm.doc.contract_start) {
                frappe.throw("Contract End cannot be before Contract Start");
            }
        }
    }
});

frappe.ui.form.on('User', {
    refresh(frm) {
        frm.add_custom_button('Send Welcome Email', function() {
            frappe.msgprint('Email Sent!');
        }, 'Actions');
    }
});
